'use strict';
/* config.ini read/write for the ExplorerBlurMica engine */
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, Math.round(Number(n) || 0)));
function buildIni(cfg) {
  const b = (v) => (v ? 'true' : 'false');
  const L = cfg.light || [255, 255, 255, 160];
  const D = cfg.dark || [0, 0, 0, 120];
  return [
    '; Generated by IBRA GLASS - engine: ExplorerBlurMica by Maplespe (LGPL-3.0)',
    '[config]',
    `effect=${clamp(cfg.effect, 0, 4)}`,
    `clearAddress=${b(cfg.clearAddress)}`,
    `clearBarBg=${b(cfg.clearBarBg)}`,
    `clearWinUIBg=${b(cfg.clearWinUIBg)}`,
    `showLine=${b(cfg.showLine)}`,
    '[light]',
    `r=${clamp(L[0], 0, 255)}`, `g=${clamp(L[1], 0, 255)}`, `b=${clamp(L[2], 0, 255)}`, `a=${clamp(L[3], 0, 255)}`,
    '[dark]',
    `r=${clamp(D[0], 0, 255)}`, `g=${clamp(D[1], 0, 255)}`, `b=${clamp(D[2], 0, 255)}`, `a=${clamp(D[3], 0, 255)}`,
    ''
  ].join('\r\n');
}
function parseIni(text) {
  const out = { light: [255, 255, 255, 255], dark: [255, 255, 255, 255] };
  let sec = '';
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith(';') || line.startsWith('#')) continue;
    const m = line.match(/^\[(.+)\]$/);
    if (m) { sec = m[1].toLowerCase(); continue; }
    const [k, ...rest] = line.split('=');
    const v = rest.join('=').trim();
    const key = k.trim();
    if (sec === 'config') {
      if (key === 'effect') out.effect = Number(v);
      else out[key] = v.toLowerCase() === 'true';
    } else if (sec === 'light' || sec === 'dark') {
      const idx = { r: 0, g: 1, b: 2, a: 3 }[key];
      if (idx !== undefined) out[sec][idx] = Number(v);
    }
  }
  return out;
}

module.exports = { buildIni, parseIni };
